<?php
$e=static fn($value)=>htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');$l=$sitepagesLabels;$url=fn(array $params=array())=>html_entity_decode($this->uri($params,'sitepages'),ENT_QUOTES,'UTF-8');$edit=is_array($sitepagesEdit)?$sitepagesEdit:array();
$iconBase=$this->getResourceUri('icons/lucide/','ui');
$icon=static fn($name)=>'<img class="chisimba-icon" src="'.htmlspecialchars($iconBase.$name.'.svg',ENT_QUOTES,'UTF-8').'" alt="" aria-hidden="true">';
?>
<main class="sitepages-admin"><header><p class="sitepages-eyebrow">SITE CONTENT</p><h1><?= $e($l['title']) ?></h1><p><?= $e($l['intro']) ?></p></header><?php if($sitepagesFlash!==''):?><p class="sitepages-notice" role="status"><?= $e($sitepagesFlash) ?></p><?php endif;?><?php if(!empty($sitepagesDenied)):?><p class="sitepages-error"><?= $e($l['forbidden']) ?></p><?php else:?><section class="sitepages-card"><div class="sitepages-card__heading"><div><h2><?= $e($l['title']) ?></h2><p><?= count($sitepagesRows) ?> page<?= count($sitepagesRows)===1?'':'s' ?></p></div><a class="button" href="<?= $e($url(array('action'=>'manage'))) ?>"><?= $icon('circle-plus') ?><span><?= $e($l['new']) ?></span></a></div><?php if(!$sitepagesRows):?><p><?= $e($l['empty']) ?></p><?php endif;?><?php foreach($sitepagesRows as $row):?><article class="sitepages-row"><div><strong><?= $e($row['title']) ?></strong><br><small>/<?= $e($row['slug']) ?> · <?= $e(ucfirst($row['status'])) ?></small></div><div class="sitepages-actions chisimba-row-actions"><a class="chisimba-icon-button" href="<?= $e($url(array('action'=>'view','slug'=>$row['slug']))) ?>" title="<?= $e($l['preview']) ?>" aria-label="<?= $e($l['preview']) ?>"><?= $icon('eye') ?></a><a class="chisimba-icon-button" href="<?= $e($url(array('action'=>'manage','id'=>$row['id']))) ?>" title="<?= $e($l['edit']) ?>" aria-label="<?= $e($l['edit']) ?>"><?= $icon('pencil') ?></a><form method="post" action="<?= $e($url()) ?>" onsubmit="return confirm(<?= $e(json_encode($l['confirmarchive'])) ?>)"><input type="hidden" name="action" value="archive"><input type="hidden" name="csrf_token" value="<?= $e($sitepagesCsrf) ?>"><input type="hidden" name="id" value="<?= $e($row['id']) ?>"><button class="chisimba-icon-button chisimba-button-danger" type="submit" title="<?= $e($l['archive']) ?>" aria-label="<?= $e($l['archive']) ?>"><?= $icon('archive') ?></button></form></div></article><?php endforeach;?></section><section class="sitepages-card"><h2><?= $e($edit?$l['edit']:$l['new']) ?></h2><form method="post" action="<?= $e($url()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="csrf_token" value="<?= $e($sitepagesCsrf) ?>"><input type="hidden" name="id" value="<?= $e($edit['id']??'') ?>"><div class="sitepages-grid"><label><?= $e($l['pagetitle']) ?><input required maxlength="250" name="title" value="<?= $e($edit['title']??'') ?>"></label><label><?= $e($l['slug']) ?><input required pattern="[a-z0-9]+(?:-[a-z0-9]+)*" name="slug" value="<?= $e($edit['slug']??'') ?>"><small><?= $e($l['slughelp']) ?></small></label></div><label><?= $e($l['status']) ?><select name="status"><option value="draft" <?= ($edit['status']??'')!=='published'?'selected':'' ?>><?= $e($l['draft']) ?></option><option value="published" <?= ($edit['status']??'')==='published'?'selected':'' ?>><?= $e($l['published']) ?></option></select></label><label><?= $e($l['content']) ?></label><?php $editor=$this->newObject('htmlarea','htmlelements');$editor->name='body_html';$editor->height='430px';$editor->width='100%';$editor->setContent($edit['body_html']??'');echo $editor->show();?><div class="sitepages-actions"><button type="submit"><?= $e($l['save']) ?></button><?php if($edit):?><a href="<?= $e($url(array('action'=>'manage'))) ?>"><?= $e($l['cancel']) ?></a><?php endif;?></div></form></section><?php endif;?></main>
